package lexer_test

// Fuzz targets: the compiler must never panic on untrusted input — malformed
// DSL yields diagnostics, not crashes. Run with:
//
//	go test ./internal/lexer -fuzz=FuzzLexer -fuzztime=30s
//
// Seed inputs below cover the representative token classes; the fuzzer grows
// the corpus automatically from there.

import (
	"testing"

	"github.com/nodecoda/ncoda/pkg/lexer"
)

func FuzzLexer(f *testing.F) {
	seeds := []string{
		"",
		"@language nodecoda/1\n",
		"function main() { return 1; }",
		"function main(string s) -> int { let x = s.length; return x; }",
		"@mode workflow\n@mode advanced-chat",
		"let x = { \"a\": 1, \"b\": [1, 2, 3] };",
		"`unterminated template",
		"@",
		"\"unterminated string",
		"foreign code python3( int x = 1 ) -> { a: int; } { source `print(x)`; };",
		"function main() { let s = \"\\x00\\x01\\xff\\xfe\\ud800\\udc00\\x7f\"; }",
		"function main() { let s = \"中文测试日本語한국어🚀emoji😀\"; return s; }",
		"function main() { let  = 1; }",
		"function main() { let x = 0; while (x < 3) { x += 1; } }",
		"let x = 99999999999999999999999999999999999999;",
		"let f = 1.7976931348623157e308; let g = 5e-324;",
		"function main() { let t = { a: { b: { c: 1 } } }; t.a.b.c += 1; }",
		"function main() { let m = { \"a\": 1 }; m.a += 1; m[\"b\"] -= 2; }",
		"let x = ((((((((((((((((((((1)))))))))))))))))))));",
		"{{ {{ {{ {{ {{ }} }} }} }} }}",
		"`unterminated ${x} ${",
		"@mode",
		"@conversation string q\nfunction main(string q) { output(\"a\", q); }",
	}
	for _, s := range seeds {
		f.Add([]byte(s))
	}
	f.Fuzz(func(t *testing.T, input []byte) {
		l := lexer.New(string(input), "fuzz.ncoda")
		_ = l.Tokenize() // must not panic
		_ = l.Errors()
	})
}
